CREATE TABLE IF NOT EXISTS device_command (id BIGSERIAL PRIMARY KEY,customer_id INTEGER NOT NULL REFERENCES customer(id),asset_id INTEGER NOT NULL REFERENCES asset(id),device_id INTEGER NOT NULL REFERENCES device(id),channel VARCHAR(30) NOT NULL DEFAULT 'DO1',action VARCHAR(30) NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'PENDING',simulation_only BOOLEAN NOT NULL DEFAULT TRUE,requested_by INTEGER NOT NULL REFERENCES "user"(id),request_token VARCHAR(64) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),expires_at TIMESTAMPTZ NOT NULL,delivered_at TIMESTAMPTZ,acknowledged_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,feedback_value DOUBLE PRECISION,failure_reason VARCHAR(240));
CREATE INDEX IF NOT EXISTS ix_device_command_device_id ON device_command(device_id);